param(
    [string]$Repo = 'C:\Users\joker\skyrim-vulkan',
    [string]$Glslang = 'C:\Program Files\RenderDoc\plugins\spirv\glslangValidator.exe'
)
# spvsync.ps1 -- gate: are the COMMITTED .spv artifacts in sync with the GLSL source?
#
# WHY (v0.18.28, 2026-10-11): CI (build.yml) runs 'cl' only -- no shader toolchain.
#   The DLL embeds pocb_shaders.h (byte arrays generated by tools\make_shaders.ps1
#   from the .spv files, which are themselves compiled locally by glslangValidator).
#   After v0.18.16 nobody re-ran make_shaders, so the v0.18.17 / v0.18.20 /
#   v0.18.27 ssr.frag changes were phantom commits: the DLL kept shipping the
#   v0.18.16 shader (miss region = raw view direction, no p6/p7 rotation = the
#   issue-B root cause; ssr.debug=9 rendered black because that old shader had
#   no debug=9 branch and fell into the debug=8 grayscale path).
#   dllchk compares DLL <-> .spv FILE; nothing compared .spv FILE <-> SOURCE.
#   This gate closes that gap: recompile every shader to TEMP and byte-compare
#   against the tracked .spv. No in-place writes => safe before or after staging.
# ASCII-only: ps1 without BOM is read as ANSI by PS 5.1.
$ErrorActionPreference = 'Stop'
if (-not (Test-Path $Glslang)) { Write-Output ("GLSLANG MISSING: " + $Glslang); exit 2 }
$shDir = Join-Path $Repo 'src\poc-presenter\shaders'
$tmp = Join-Path $env:TEMP 'spvsync'
if (-not (Test-Path $tmp)) { New-Item -ItemType Directory -Path $tmp | Out-Null }
$pairs = @(
    @{ src = 'pocb.vert'; stage = 'vert' },
    @{ src = 'pocb.frag'; stage = 'frag' },
    @{ src = 'ssr.vert'; stage = 'vert' },
    @{ src = 'ssr.frag'; stage = 'frag' },
    @{ src = 'sky_probe.frag'; stage = 'frag' },
    @{ src = 'sky_lut.frag'; stage = 'frag' },
    @{ src = 'sky_cloud.frag'; stage = 'frag' },
    @{ src = 'sky_comp.frag'; stage = 'frag' }
)
$fail = 0
foreach ($p in $pairs) {
    $src = Join-Path $shDir $p.src
    $ref = Join-Path $shDir ($p.src + '.spv')
    $out = Join-Path $tmp ($p.src + '.spv')
    & $Glslang -V -S $p.stage -o $out $src | Out-Null
    if ($LASTEXITCODE -ne 0 -or -not (Test-Path $out)) { Write-Output ("COMPILE FAIL: " + $p.src); $fail++; continue }
    $a = [System.IO.File]::ReadAllBytes($out)
    $b = [System.IO.File]::ReadAllBytes($ref)
    $sync = ($a.Length -eq $b.Length)
    if ($sync) {
        for ($i = 0; $i -lt $a.Length; $i++) { if ($a[$i] -ne $b[$i]) { $sync = $false; break } }
    }
    Write-Output ("{0,-11} recompiled={1}B tracked={2}B sync={3}" -f $p.src, $a.Length, $b.Length, $sync)
    if (-not $sync) { $fail++ }
}
if ($fail -gt 0) {
    Write-Output ("SPVSYNC FAIL (" + $fail + " out of sync) -- run tools\make_shaders.ps1 and commit the regenerated .spv + pocb_shaders.h")
    exit 1
}
Write-Output 'SPVSYNC OK -- tracked spv matches GLSL source'
exit 0
